// Event counters in the core clock domain. Capture and display frame events
// are independent; level signals are deliberately not counted repeatedly.
// interval_tick is a real one-second pulse generated by the integration top.
module video_status_counters(
  input logic clk,rst_n,
  input logic frame_start,              // capture frame complete (legacy name)
  input logic display_frame_start,
  input logic raw_frame_start,
  input logic capture_overflow,display_underflow,axi_error,
  input logic interval_tick,
  output logic [31:0] capture_frames,display_frames,drop_count,underflow_count,error_count,
  output logic [15:0] capture_fps,display_fps,raw_fps
);
  logic [31:0] cap_interval,disp_interval,raw_interval;
  logic overflow_d,underflow_d,axi_error_d;
  always_ff @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin capture_frames<=0;display_frames<=0;drop_count<=0;underflow_count<=0;error_count<=0;capture_fps<=0;display_fps<=0;raw_fps<=0;cap_interval<=0;disp_interval<=0;raw_interval<=0;overflow_d<=0;underflow_d<=0;axi_error_d<=0; end
    else begin
      if(frame_start) begin capture_frames<=capture_frames+1'b1;cap_interval<=cap_interval+1'b1;end
      if(display_frame_start) begin display_frames<=display_frames+1'b1;disp_interval<=disp_interval+1'b1;end
      if(raw_frame_start) raw_interval<=raw_interval+1'b1;
      if(capture_overflow && !overflow_d) drop_count<=drop_count+1'b1;
      if(display_underflow && !underflow_d) underflow_count<=underflow_count+1'b1;
      if(axi_error && !axi_error_d) error_count<=error_count+1'b1;
      overflow_d<=capture_overflow; underflow_d<=display_underflow; axi_error_d<=axi_error;
      if(interval_tick) begin
        capture_fps <= (cap_interval + (frame_start?1:0) > 32'hffff) ? 16'hffff : cap_interval[15:0] + (frame_start?16'd1:16'd0);
        display_fps <= (disp_interval + (display_frame_start?1:0) > 32'hffff) ? 16'hffff : disp_interval[15:0] + (display_frame_start?16'd1:16'd0);
        raw_fps <= (raw_interval + (raw_frame_start?1:0) > 32'hffff) ? 16'hffff : raw_interval[15:0] + (raw_frame_start?16'd1:16'd0);
        cap_interval<=0;disp_interval<=0;raw_interval<=0;
      end
    end
  end
endmodule
